module fifo4 (
    input clk,
    input reset,
    input wr_en,
    input rd_en,
    input [7:0] din,
    output reg [7:0] dout,
    output reg full,
    output reg empty,
    output reg [2:0] count
);

    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg [7:0] mem [0:3];

    always @(posedge clk) begin
        if (reset) begin
            wr_ptr <= 2'd0;
            rd_ptr <= 2'd0;
            count <= 3'd0;
            full <= 1'b0;
            empty <= 1'b1;
            dout <= 8'd0;
        end else begin
            if (wr_en && !full) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 1;
                count <= count + 1;
            end
            if (rd_en && !empty) begin
                dout <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 1;
                count <= count - 1;
            end
            full <= (count == 3'd4);
            empty <= (count == 3'd0);
        end
    end

endmodule

