reg [2:0] next_state;
reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        count <= 4'd0;
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            if (count == 3'd3) begin
                next_state <= 3'd1;
                count <= 4'd0;
            end else begin
                next_state <= state;
                count <= count + 1;
            end
        end else if (state == 3'd1) begin
            if (count == 4'd4) begin
                next_state <= 3'd2;
                count <= 4'd0;
            end else begin
                next_state <= state;
                count <= count + 1;
            end
        end else if (state == 3'd2) begin
            if (count == 2'd2) begin
                next_state <= 3'd0;
                count <= 4'd0;
            end else begin
                next_state <= state;
                count <= count + 1;
            end
        end
    end
